"""Train a pre-trained YOLOv11 segmentation model on a custom dataset using specified parameters."""from ultralytics import YOLO# vortrainiertes YOLO11 Segmentation Modellmodel = YOLO("yolo11n-seg.yaml")  # architecture only# Training startenmodel.train(    data="/Users/leonhofmann/Desktop/MMES/Protject 2/Yolo11/Modelparams/dataset.yaml",    epochs=10,       # zum Testen erstmal 10    imgsz=640,       # Bildgröße    batch=2,         # kleiner Batch falls wenig RAM/GPU    project="/Users/leonhofmann/Desktop/MMES/Protject 2/Yolo11/runs", # Speicherort für Outputs    name="test_train"  # Name des Trainingslaufs)